L10_1.m_Talk_THA = "\224\184\129\224\184\163\224\184\176\224\184\153\224\184\177\224\185\137\224\184\153 \224\184\158\224\184\180\224\184\169\224\184\162\224\184\177\224\184\135\224\184\132\224\184\135\224\184\171\224\184\165\224\184\135\224\185\128\224\184\171\224\184\165\224\184\183\224\184\173\224\184\173\224\184\162\224\184\185\224\185\136\224\185\131\224\184\153\224\185\130\224\184\165\224\184\129\224\184\153\224\184\181\224\185\137... \224\184\171\224\184\178\224\184\129\224\184\161\224\184\180\224\184\173\224\184\178\224\184\136\224\184\132\224\184\167\224\184\154\224\184\132\224\184\184\224\184\161\224\185\132\224\184\148\224\185\137\224\184\132\224\184\135\224\184\165\224\185\136\224\184\161\224\184\170\224\184\165\224\184\178\224\184\162\224\185\128\224\184\155\224\185\135\224\184\153\224\185\129\224\184\153\224\185\136"
L10_1.m_Talk_VTN = "Tuy nhi\195\170n, n\225\187\141c \196\145\225\187\153c c\225\187\167a mi v\225\186\171n r\225\186\163i r\195\161c trong th\225\186\191 gi\225\187\155i n\195\160y...v\195\160 th\225\186\191 gi\225\187\155i s\225\186\189 \196\145\225\187\149 n\195\161t n\225\186\191u kh\195\180ng \196\145\198\176\225\187\163c ki\225\187\131m so\195\161t."
L10_1.m_Talk_SCN = "\228\189\134\228\189\160\231\154\132\230\175\146\230\176\148\232\191\152\229\156\168\230\145\167\230\175\129\231\142\176\228\184\150\226\128\166\226\128\166\231\133\167\232\191\153\230\160\183\228\184\139\229\142\187\239\188\140\228\184\150\231\149\140\231\187\136\229\176\134\229\136\134\229\180\169\231\166\187\230\158\144\227\128\130"
L10_1.m_Talk_DEU = "Aber dein Gift zerst\195\182rt immer noch diese Welt ... Wenn das so weitergeht, dann ist die Welt dem Untergang geweiht."
L10_1.m_Talk_FRA = "Pourtant ton venin, lui, continue de se r\195\169pandre... si je ne fais rien, ce monde finira par s'\195\169crouler."
