L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "\227\129\157\227\130\140\227\130\134\227\129\136\227\128\129\227\129\138\228\184\187\227\129\174\230\156\128\229\190\140\227\129\174\233\160\173\227\130\146\229\136\135\227\130\138\229\143\150\227\130\137\227\129\173\227\129\176\227\129\170\227\130\137\227\129\172\227\128\130\231\150\171\231\151\133\231\165\158\227\130\170\227\131\173\227\131\129\227\130\136\227\128\130"
