L11_1.m_Talk_VTN = "V\195\172 v\225\186\173y, ta s\225\186\189 ch\225\186\183t \196\145\225\187\169t c\225\186\163 c\195\161i \196\145\225\186\167u cu\225\187\145i c\195\185ng c\225\187\167a mi, Th\225\186\167n B\225\187\135nh D\225\187\139ch Orochi \195\160."
L11_1.m_Talk_SCN = "\230\137\128\228\187\165\239\188\140\230\136\145\232\166\129\231\160\141\230\142\137\228\189\160\230\156\128\229\144\142\228\184\128\228\184\170\232\132\145\232\162\139\239\188\140\231\152\159\231\165\158\229\164\167\232\155\135\227\128\130"
