L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "\230\136\145\227\129\175\230\173\187\227\129\170\227\130\147\227\128\130\228\186\161\232\128\133\227\130\146\230\178\187\227\130\129\227\130\139\232\178\180\230\167\152\227\129\170\227\130\137\227\130\136\227\129\143\231\159\165\227\129\163\227\129\166\227\129\132\227\130\139\227\129\175\227\129\154\227\129\160\227\128\130"
L12_1.m_Talk_ENG = "I am immortal. You, the ruler of death, should know this, no?"
L12_1.m_Talk_TWN = "\233\128\153\229\137\175\232\187\128\233\171\148\230\152\175\228\184\141\230\156\131\230\173\187\231\154\132\239\188\140\231\174\161\231\144\134\230\173\187\228\186\186\231\154\132\228\189\160\230\135\137\232\169\178\229\190\136\230\184\133\230\165\154\229\144\167\239\188\159"
