L12_1.m_Talk_VTN = "Ta l\195\160 b\225\186\165t t\225\187\173. M\225\187\153t k\225\186\187 th\225\187\145ng tr\225\187\139 c\195\161i ch\225\186\191t h\225\186\179n ph\225\186\163i bi\225\186\191t \196\145i\225\187\129u n\195\160y, \196\145\195\186ng ch\225\187\169?"
L12_1.m_Talk_SCN = "\230\136\145\228\184\141\228\188\154\230\173\187\227\128\130\230\142\140\231\174\161\228\186\161\232\128\133\231\154\132\228\189\160\229\186\148\232\175\165\229\190\136\230\184\133\230\165\154\230\137\141\229\175\185\229\144\167\239\188\159"
